  for (size_t i = 0; i < sizeof(body); ++i) {
    size_t shift_amount = (sizeof(body) - 1 - i) * 8;
    bytes[i + 2] = static_cast<char>((body >> shift_amount) & 0xFF);
  }

  return bytes;
}

